using System;using System.IO;using System.Linq;using UnityEngine;using Bokumyaku.Presentation;public static class HudSpacingCheck{static Rect R(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();g.SetPaused(true);var h=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();Canvas.ForceUpdateCanvases();var all=h.GetComponentsInChildren<RectTransform>(true);Func<string,Rect> r=n=>R(all.Single(x=>x.name==n));if(r("WaveTitle").Overlaps(r("Wave"))||r("Level0").Overlaps(r("Repair"))||r("Level0").Overlaps(r("CoreTrack"))||r("Level0").Overlaps(r("Upgrade0")))throw new Exception("HUD overlap");var report=new{passed=true,width=Screen.width,height=Screen.height,levelGap=r("CoreTrack").yMin-r("Level0").yMax,repairHeight=r("Repair").height};File.WriteAllText(Path.GetFullPath("../docs/evidence/hud-spacing.json"),Newtonsoft.Json.JsonConvert.SerializeObject(report));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/hud-spacing.png"));return report;}}
